{
  "references": [
    {
      "id": "R1",
      "summary_ko": "카메라 각도는 변하지 않고 장면만 바뀌며, 작업자가 기계를 사용하는 모습에서 측정 작업을 하는 다른 장면으로 전환됨."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "영상 특징과 픽셀 구조가 함께 변하여 형태 및 존재 변화 가능성이 감지된 구간."
    },
    {
      "id": "C2",
      "summary_ko": "영상 특징과 픽셀 구조가 함께 변하여 형태 및 존재 변화 가능성이 감지된 구간."
    },
    {
      "id": "C3",
      "summary_ko": "앵글 그라인더를 사용하는 동안 그라인딩 불꽃이 강한 용접 아크 빛으로 변형됨."
    },
    {
      "id": "C4",
      "summary_ko": "약 2.875초경 작업자가 다른 도구와 부품을 다루는 위에서 내려다보는 시점으로 장면이 갑자기 전환됨."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "C1은 구체적 대상이 특정되지 않은 일반적인 측정 가설이므로, 참조 설명의 장면 전환과 동일한 현상인지 텍스트만으로는 확정할 수 없습니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "uncertain",
      "reason_ko": "C2는 대상을 식별하지 않은 일반적인 측정 가설로, 장면 전환 현상과 직접 일치하는지 확인할 수 없습니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "R1은 작업 장면의 급격한 전환을 설명하지만, C3는 그라인딩 불꽃이 용접 아크 빛으로 변형되는 이상 현상을 설명하여 대상과 결함 내용이 완전히 다릅니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C4",
      "verdict": "same",
      "reason_ko": "두 설명 모두 작업자의 행동과 장면이 다른 도구를 다루는 상황으로 갑작스럽게 전환/컷되는 동일한 비디오 장면 전환 결함을 설명하고 있습니다."
    }
  ]
}
